const RULES_BY_VARIANT_CACHE = new Map<ConditionVariant, ClinicalSuitabilityRule[]>();
const RULE_BY_KEY_CACHE = new Map<string, ClinicalSuitabilityRule>();

for (const rule of CLINICAL_RULES_SEED) {
  if (!RULES_BY_VARIANT_CACHE.has(rule.conditionVariant)) {
    RULES_BY_VARIANT_CACHE.set(rule.conditionVariant, []);
  }
  RULES_BY_VARIANT_CACHE.get(rule.conditionVariant)!.push(rule);
  RULE_BY_KEY_CACHE.set(`${rule.conditionVariant}__${rule.nutrientName}`, rule);
}

export function getRulesForVariant(variant: ConditionVariant): ClinicalSuitabilityRule[] {
  return RULES_BY_VARIANT_CACHE.get(variant) || [];
}

export function getClinicalRule(variant: ConditionVariant, nutrient: keyof NutrientVector12): ClinicalSuitabilityRule | undefined {
  return RULE_BY_KEY_CACHE.get(`${variant}__${nutrient}`);
}
